using Orleans;
namespace GameServer.Contracts;
public interface IAccountGrain : IGrainWithStringKey { Task<CreateCharacterResult> CreateCharacterAsync(string name, string contentVersion, string? classId = null); Task<IReadOnlyList<CharacterSummary>> GetCharactersAsync(); Task<bool> OwnsCharacterAsync(string characterId); }
public interface ICharacterGrain : IGrainWithStringKey { Task InitializeAsync(string accountId, string name, string contentVersion, string classId); Task<CharacterSnapshot> GetSnapshotAsync(); Task<CharacterSnapshotV2> GetSnapshotV2Async(); Task<CommandResult> EnterZoneAsync(string zoneId, string contentVersion); Task<CommandResult> MoveAsync(MoveCommand command, string operationId); Task<CommandResult> AttackAsync(AttackCommand command, string operationId); Task<CommandResult> UseSkillAsync(UseSkillCommand command, string operationId); Task<CommandResult> EquipAsync(EquipCommand command, string operationId); Task<CommandResult> UnequipAsync(UnequipCommand command, string operationId); Task<CommandResult> InteractNpcAsync(InteractNpcCommand command, string operationId); Task<CommandResult> AcceptQuestAsync(QuestCommand command, string operationId); Task<CommandResult> CompleteQuestAsync(QuestCommand command, string operationId); }
public interface IZoneGrain : IGrainWithStringKey { Task<ZoneSnapshot> JoinAsync(string characterId, WorldPosition position, string contentVersion); Task LeaveAsync(string characterId); Task<bool> MoveAsync(string characterId, WorldPosition position); Task<bool> IsNearNpcAsync(string characterId, string npcId); Task<AttackResult> AttackMonsterAsync(string characterId, string monsterId, decimal damage, decimal range, string operationId); Task<ZoneSnapshot> GetSnapshotAsync(); }
public interface IMonsterGrain : IGrainWithStringKey { Task InitializeAsync(MonsterDefinition definition); Task<AttackResult> ApplyDamageAsync(decimal damage, string operationId); Task<ZoneEntity> GetSnapshotAsync(); }
